begin;
create type public.app_role as enum ('learner','admin');
create type public.content_status as enum ('draft','review','published','archived');
create type public.submission_status as enum ('draft','submitted','under_review','revision_required','approved');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role public.app_role not null default 'learner',preferred_language text not null default 'en' check(preferred_language in('en','ar')),learning_pathway text default 'general_management',weekly_target_hours numeric(4,1) default 8 check(weekly_target_hours between 1 and 40),account_status text not null default 'active' check(account_status in('active','suspended','deleted')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.programs(id uuid primary key default gen_random_uuid(),slug text unique not null,title_en text not null,title_ar text,description_en text,description_ar text,status public.content_status not null default 'draft',created_at timestamptz default now());
create table public.modules(id uuid primary key default gen_random_uuid(),program_id uuid references public.programs on delete cascade,sequence int not null,title_en text not null,title_ar text,summary_en text,summary_ar text,estimated_hours numeric(4,1) default 8,pass_score int default 70 check(pass_score between 0 and 100),status public.content_status default 'draft',unique(program_id,sequence));
create table public.lessons(id uuid primary key default gen_random_uuid(),module_id uuid references public.modules on delete cascade,sequence int not null,title_en text not null,title_ar text,content_en text,content_ar text,estimated_minutes int default 30,status public.content_status default 'draft',version int default 1,created_at timestamptz default now(),updated_at timestamptz default now(),unique(module_id,sequence));
create table public.lesson_progress(user_id uuid references public.profiles on delete cascade,lesson_id uuid references public.lessons on delete cascade,percent int default 0 check(percent between 0 and 100),time_spent_minutes int default 0,completed_at timestamptz,updated_at timestamptz default now(),primary key(user_id,lesson_id));
create table public.assignments(id uuid primary key default gen_random_uuid(),module_id uuid references public.modules on delete cascade,title_en text not null,title_ar text,instructions_en text,instructions_ar text,max_score int default 100,status public.content_status default 'draft');
create table public.submissions(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles on delete cascade,assignment_id uuid references public.assignments on delete cascade,storage_path text not null,original_name text not null,mime_type text,file_size bigint check(file_size<=26214400),learner_comments text,version int default 1,status public.submission_status default 'submitted',score numeric(5,2),feedback text,submitted_at timestamptz default now(),reviewed_at timestamptz);
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references public.profiles,action text not null,object_type text not null,object_id text,old_values jsonb,new_values jsonb,created_at timestamptz default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name) values(new.id,new.raw_user_meta_data->>'full_name');return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role='admin' and account_status='active')$$;
alter table public.profiles enable row level security;alter table public.programs enable row level security;alter table public.modules enable row level security;alter table public.lessons enable row level security;alter table public.lesson_progress enable row level security;alter table public.assignments enable row level security;alter table public.submissions enable row level security;alter table public.audit_logs enable row level security;
create policy profiles_self_select on public.profiles for select using(id=auth.uid() or public.is_admin());
create or replace function public.update_my_profile(p_full_name text,p_language text,p_pathway text,p_weekly_hours numeric) returns void language plpgsql security definer set search_path=public as $$begin if p_language not in ('en','ar') or p_weekly_hours not between 1 and 40 then raise exception 'Invalid profile values'; end if; update public.profiles set full_name=p_full_name,preferred_language=p_language,learning_pathway=p_pathway,weekly_target_hours=p_weekly_hours,updated_at=now() where id=auth.uid();end$$;
grant execute on function public.update_my_profile(text,text,text,numeric) to authenticated;
create policy programs_read on public.programs for select using(status='published' or public.is_admin());create policy programs_admin on public.programs for all using(public.is_admin()) with check(public.is_admin());
create policy modules_read on public.modules for select using(status='published' or public.is_admin());create policy modules_admin on public.modules for all using(public.is_admin()) with check(public.is_admin());
create policy lessons_read on public.lessons for select using(status='published' or public.is_admin());create policy lessons_admin on public.lessons for all using(public.is_admin()) with check(public.is_admin());
create policy progress_own on public.lesson_progress for all using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin());
create policy assignments_read on public.assignments for select using(status='published' or public.is_admin());create policy assignments_admin on public.assignments for all using(public.is_admin()) with check(public.is_admin());
create policy submissions_own_select on public.submissions for select using(user_id=auth.uid() or public.is_admin());create policy submissions_own_insert on public.submissions for insert with check(user_id=auth.uid());create policy submissions_own_update on public.submissions for update using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin());
create policy audit_admin_read on public.audit_logs for select using(public.is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('assignments','assignments',false,26214400,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.openxmlformats-officedocument.presentationml.presentation','image/jpeg','image/png']) on conflict(id) do nothing;
create policy assignment_upload on storage.objects for insert to authenticated with check(bucket_id='assignments' and (storage.foldername(name))[1]=auth.uid()::text);create policy assignment_read on storage.objects for select to authenticated using(bucket_id='assignments' and ((storage.foldername(name))[1]=auth.uid()::text or public.is_admin()));create policy assignment_delete on storage.objects for delete to authenticated using(bucket_id='assignments' and ((storage.foldername(name))[1]=auth.uid()::text or public.is_admin()));
commit;